"""Backspace String Compare — compare from the right, skipping deletions.

Walking backwards lets you honour '#' without building either string.

Time: O(n + m)   Space: O(1)
"""


class Solution:
    def backspaceCompare(self, s: str, t: str) -> bool:
        def next_char(text: str, i: int) -> int:
            skip = 0
            while i >= 0:
                if text[i] == "#":
                    skip += 1
                elif skip:
                    skip -= 1
                else:
                    return i
                i -= 1
            return -1

        i, j = len(s) - 1, len(t) - 1
        while i >= 0 or j >= 0:
            i, j = next_char(s, i), next_char(t, j)
            if i >= 0 and j >= 0:
                if s[i] != t[j]:
                    return False
            elif i >= 0 or j >= 0:
                return False
            i -= 1
            j -= 1
        return True
